// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        Attacker attacker = new Attacker();

        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.deposit{value: amount}();

        attacker.setTarget(address(c));

        vm.prank(address(attacker));
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}

contract Attacker {
    address target;

    function setTarget(address t) external { target = t; }

    receive() external payable {
        // Re-enter withdrawAll once during the payout.
        ReentrancyDAO(target).withdrawAll();
    }
}
